lessons.push(...[{"id":"exp-20261102c-01","subject":"商業簿記","topic":"引当金","title":"キャッシュ・フロー見積法の基本","body":"貸倒懸念債権について、元本・利息の回収見込額を当初の約定利子率で割り引いた現在価値と帳簿価額の差額を貸倒見積額とします。例：帳簿価額1,000,000円、1年後に元利合計880,000円を回収、当初約定利率10％なら現在価値は880,000÷1.1＝800,000円、見積額は200,000円です。","tag":"商業簿記｜引当金","sourceUrl":"https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-20261102c-02","subject":"会計学","topic":"引当金","title":"割引計算と期末の引当金","body":"将来の入金を現在価値に換算して貸倒見積額を計算したら、同じ債権の既存引当金との差を期末に調整します。帳簿価額1,000,000円、回収見込現在価値750,000円、引当金残高100,000円なら、必要額250,000円との差額150,000円を繰り入れます。","tag":"会計学｜引当金","sourceUrl":"https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-20261102c-03","subject":"工業簿記","topic":"工原：実際総合原価計算","title":"仕損の発生点と月末仕掛品","body":"正常仕損費を負担するのは、仕損が発生する工程を通過した製品です。例：正常仕損が加工進捗80％で発生、完成品90個、月末仕掛品20個は加工40％なら、仕掛品は発生点未通過なので正常仕損費は完成品だけが負担します。","tag":"工業簿記｜工原：実際総合原価計算","sourceUrl":"https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-20261102c-04","subject":"原価計算","topic":"工原：実際総合原価計算","title":"材料始点投入と仕損の配分","body":"材料費が始点投入で、正常仕損が始点で発生し、その費用を完成品と月末仕掛品に数量比例で負担させる設例を考えます。完成90個、月末10個、正常仕損費20,000円なら完成品18,000円、月末仕掛品2,000円です。仕損品の処分価値はないとします。","tag":"原価計算｜工原：実際総合原価計算","sourceUrl":"https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]}]);
qs.push(...[{"id":"exp-q-20261102c-01","subject":"商業簿記","topic":"引当金","q":"債権帳簿価額1,200,000円、1年後の元利回収見込額1,100,000円、当初約定利率10％。貸倒見積額は？","a":["200,000円","100,000円","1,000,000円"],"correct":0,"ex":"回収見込額の現在価値＝1,100,000÷1.1＝1,000,000円。貸倒見積額＝1,200,000−1,000,000＝200,000円。","sourceUrl":"https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-q-20261102c-02","subject":"会計学","topic":"引当金","q":"貸倒見積額250,000円、同一債権に対する期末整理前引当金100,000円。差額補充の仕訳は？","a":["借：貸倒引当金繰入150,000／貸：貸倒引当金150,000","借：貸倒引当金繰入250,000／貸：貸倒引当金250,000","借：貸倒引当金150,000／貸：貸倒引当金繰入150,000"],"correct":0,"ex":"250,000−100,000＝150,000円を追加計上します。","sourceUrl":"https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-q-20261102c-03","subject":"工業簿記","topic":"工原：実際総合原価計算","q":"正常仕損が加工進捗80％で発生し、完成品100個、月末仕掛品20個の加工進捗は40％。正常仕損費を負担するのは？","a":["完成品のみ","完成品と月末仕掛品","月末仕掛品のみ"],"correct":0,"ex":"月末仕掛品の40％は発生点80％に達していません。正常仕損費は完成品が負担します。","sourceUrl":"https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]},{"id":"exp-q-20261102c-04","subject":"原価計算","topic":"工原：実際総合原価計算","q":"材料は始点投入、正常仕損も始点発生。正常仕損費30,000円を完成80個と月末仕掛20個で数量比例負担する。月末仕掛品の負担額は？","a":["6,000円","24,000円","30,000円"],"correct":0,"ex":"負担割合は20÷（80＋20）＝20％。30,000×20％＝6,000円。","sourceUrl":"https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf","sourceLabel":"基準・出題区分表","reviewed":"2026-11-02","years":[2026,2027]}]);
